  section.innerHTML='<div class="sale-return-summary-head"><div><strong>Devoluções registradas</strong><small>Produtos e valores já devolvidos nesta venda</small></div><b>Total devolvido: '+returnMoney(total)+'</b></div><table><thead><tr><th>Devolução</th><th>Produto ou serviço</th><th>Quantidade devolvida</th><th>Valor devolvido</th><th>Data</th></tr></thead><tbody>'+entries.map(function(x){return'<tr><td>'+escapeReturnHtml(x.returnCode)+'</td><td>'+escapeReturnHtml(x.name)+'</td><td>'+escapeReturnHtml(x.qty)+'</td><td>'+returnMoney(x.total)+'</td><td>'+escapeReturnHtml(x.date)+'</td></tr>'}).join('')+'</tbody></table>';
