  const oldFilter=filterSalesRows;
  filterSalesRows=function(mode){if(localStorage.getItem('activeSalesTab')==='returns'||document.querySelector('.sales-table')?.dataset.returnsView==='1')return;ensureStatusColumn();refreshQuoteBadges();localStorage.setItem('activeSalesTab',mode);document.querySelectorAll('#saleRows tr').forEach(r=>{if(r.id==='returnsEmptyRow')return;const hide=mode==='quotes'?rowType(r)!=='orçamento':rowType(r)!=='venda';r.hidden=hide;r.classList.toggle('hidden',hide);r.style.display=hide?'none':''});document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));const target=document.getElementById(mode==='quotes'?'quotesTab':'salesTab');if(target)target.classList.add('active')};
