  setupQuoteTab=function(){oldSetupQuoteTab();refreshQuoteBadges();filterSalesRows(localStorage.getItem('activeSalesTab')==='quotes'?'quotes':'sales')};
  document.addEventListener('click',function(e){const tab=e.target.closest('#salesTab,#quotesTab');if(tab&&location.hash==='#devolVendas')history.replaceState(null,'',location.pathname+location.search)},true);
  const oldSaveSale=saveSale;
  saveSale=function(){const type=document.querySelector('.form-grid select')?.value,editing=editingCode,client=document.getElementById('client')?.value.trim();oldSaveSale();if(type!=='Orçamento'&&type!=='Venda')return;const saved=JSON.parse(localStorage.getItem('localSales')||'[]'),code=editing||String(Math.max(0,...saved.map(x=>Number(x.code)||0))),sale=saved.find(x=>String(x.code)===String(code));if(sale){sale.quoteStatus=type==='Orçamento'?(document.getElementById('quoteStatus')?.value||'pending'):'converted';localStorage.setItem('localSales',JSON.stringify(saved))}setTimeout(refreshQuoteBadges,0)};
  document.addEventListener('DOMContentLoaded',function(){const s=document.getElementById('quoteStatus');if(s)s.innerHTML='<option value="pending">Aguardando aprovação</option><option value="approved">Aprovado</option><option value="rejected">Reprovado</option><option value="converted">Convertido em venda</option>';setTimeout(function(){refreshQuoteBadges();filterSalesRows(localStorage.getItem('activeSalesTab')==='quotes'?'quotes':'sales')},0)});
  document.addEventListener('click',function(e){const tab=e.target.closest('#salesTab,#quotesTab');if(!tab)return;e.preventDefault();e.stopImmediatePropagation();const mode=tab.id==='quotesTab'?'quotes':'sales';if(typeof window.restoreSalesView==='function')window.restoreSalesView();localStorage.setItem('activeSalesTab',mode);document.querySelectorAll('#saleRows tr').forEach(function(row){if(row.cells.length===7){const statusCell=document.createElement('td');statusCell.dataset.quoteStatusCell='1';row.insertBefore(statusCell,row.cells[row.cells.length-1])}const type=(row.cells[5]?.textContent||'').trim().toLowerCase();const hide=mode==='quotes'?type!=='orçamento':type==='orçamento';row.hidden=hide;row.style.display=hide?'none':'';if(type==='orçamento'){const cell=row.cells[6];if(cell&&!cell.textContent.trim()){const badge=document.createElement('span');badge.className='quote-status quote-status-pending';badge.textContent='AGUARDANDO APROVAÇÃO';cell.appendChild(badge)}}});document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active')},true);
  document.addEventListener('DOMContentLoaded',function(){new MutationObserver(function(){if(document.querySelector('.form-grid'))setupQuoteControls();ensureStatusColumn();refreshQuoteBadges();filterSalesRows(localStorage.getItem('activeSalesTab')==='quotes'?'quotes':'sales')}).observe(document.body,{childList:true,subtree:true});setTimeout(function(){setupQuoteControls();ensureStatusColumn();refreshQuoteBadges();filterSalesRows(localStorage.getItem('activeSalesTab')==='quotes'?'quotes':'sales')},0)});
  document.addEventListener('click',function(e){const row=e.target.closest('#saleRows tr');if(!row)return;setTimeout(function(){const s=document.getElementById('quoteStatus');if(s){const value=statusFor(row);s.value=value||'pending'}},0)});
